-- Receipt cancellation, same day (docs/designs/receipt-cancel): ACTIVE -> CANCELLED on the receipt's own day (IST), with a
-- fresh step-up, a reason, and nothing else changed; outstanding returns through fee_due_balance. Head generated by prisma migrate diff.
-- AlterTable
ALTER TABLE "app"."receipt" ADD COLUMN     "cancel_reason" TEXT,
ADD COLUMN     "cancelled_at" TIMESTAMPTZ,
ADD COLUMN     "cancelled_by" UUID;

-- AddForeignKey
ALTER TABLE "app"."receipt" ADD CONSTRAINT "receipt_cancelled_by_fkey" FOREIGN KEY ("cancelled_by") REFERENCES "app"."app_user"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;



-- ---------- Named check: the three cancel fields together, exactly when CANCELLED (Z8-4) ----------
alter table app.receipt add constraint receipt_cancel_check check (
  num_nonnulls(cancelled_at, cancelled_by, cancel_reason) = case when status = 'CANCELLED' then 3 else 0 end
  and (cancel_reason is null or (cancel_reason = btrim(cancel_reason) and char_length(cancel_reason) between 1 and 500)));

-- ---------- The only update: ACTIVE -> CANCELLED, on the receipt's own day (IST), with a fresh step-up, nothing else
-- changed (fee-receipts D11). Rules only, so it binds every role; nested ifs; each message carries its constraint name.
-- The ticket piece (after the day) replaces step 3; F1 and the ticket piece name their own columns in step 6. ----------
create function app.receipt_cancel_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
begin
  perform pg_advisory_xact_lock(hashtext('fee-dues:' || old.registration_id::text));
  if old.status is distinct from 'ACTIVE' or new.status is distinct from 'CANCELLED' then
    raise exception 'a receipt only goes from ACTIVE to CANCELLED: constraint "receipt_cancel_status_guard"' using errcode = '23514', constraint = 'receipt_cancel_status_guard';
  end if;
  if old.received_on is distinct from (now() at time zone 'Asia/Kolkata')::date then
    raise exception 'a receipt is cancelled on its own day; later, by ticket: constraint "receipt_cancel_late_guard"' using errcode = '23514', constraint = 'receipt_cancel_late_guard';
  end if;
  -- the step-up, also for raw SQL (D2); 300 = POLICY.stepUpMaxAgeSeconds (asserted by T-RC-002)
  if app.session_user_id() is not null then
    if not app.session_step_up_fresh(300) then
      raise exception 'cancelling needs a fresh step-up: constraint "receipt_cancel_stepup_guard"' using errcode = '23514', constraint = 'receipt_cancel_stepup_guard';
    end if;
  end if;
  new.cancelled_at := now();
  new.cancelled_by := coalesce(app.session_user_id(), new.cancelled_by);
  if (to_jsonb(new) - 'status' - 'cancelled_at' - 'cancelled_by' - 'cancel_reason')
     is distinct from (to_jsonb(old) - 'status' - 'cancelled_at' - 'cancelled_by' - 'cancel_reason') then
    raise exception 'a cancel changes nothing else: constraint "receipt_cancel_frozen_guard"' using errcode = '23514', constraint = 'receipt_cancel_frozen_guard';
  end if;
  return new;
end $$;
drop trigger receipt_no_update_delete on app.receipt;
create trigger receipt_no_delete before delete on app.receipt for each row execute function app.ticket_immutable();
create trigger receipt_cancel_guard before update on app.receipt for each row execute function app.receipt_cancel_guard();

-- ---------- RLS: fee.receipt.cancel updates at its centres; delete never; lines unchanged ----------
drop policy receipt_update on app.receipt;
create policy receipt_update on app.receipt for update
  using (centre_id = any ((select app.scoped_centre_ids('fee.receipt.cancel'))::int[]))
  with check (centre_id = any ((select app.scoped_centre_ids('fee.receipt.cancel'))::int[]));

-- ---------- Permission (sensitive: holders keep TOTP mandatory once the role is assigned, 0005/0013) ----------
insert into app.permission (key, description, sensitive) values
  ('fee.receipt.cancel', 'Cancel a fee receipt on its day', true)
on conflict (key) do nothing;
insert into app.role_permission (role_id, permission_key) select id, 'fee.receipt.cancel' from app.role where key = 'system_admin'
on conflict do nothing;

-- ---------- Grant: a new update grant (0027 granted none); who and when are the guard's ----------
grant update (status, cancel_reason) on app.receipt to gems_app;
